public class ProblemB {

    private void solve(char[] a, PrintWriter out) {
        int i = 0;
        int one = 0;
        int two = 0;
        boolean insideParenthesis = false;
        while (i != a.length) {
            if (a[i] == '(') {
                insideParenthesis = true;
            } else if (a[i] == ')') {
                insideParenthesis = false;
            } else if (Character.isLetter(a[i]))
                i--;
            if (insideParenthesis) { // inside
                while (++i != a.length && a[i] != ')' && !Character.isLetter(a[i]));
                if (i == a.length || !Character.isLetter(a[i])) {
                    continue;
                }
                while (Character.isLetter(a[++i]));
                two++;
            } else {
                while (++i != a.length && a[i] != '(' && !Character.isLetter(a[i]));
                if (i == a.length || !Character.isLetter(a[i])) {
                    continue;
                }

                int j = i;
                while (++i != a.length && Character.isLetter(a[i]));
                one = Math.max(one, i - j);
            }
        }
        out.println(one + " " + two);
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(args.length == 0 ? System.in : new FileInputStream(args[0])));
                PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            in.readLine();
            new ProblemB().solve(in.readLine().toCharArray(), out);
        }
    }
}

