int main(int argc, char* argv[]) {
    std::istream* in_stream = &std::cin;
    std::ifstream file;
    if (argc > 1) {
        file.open(argv[1]);
        if (file.is_open()) {
            in_stream = &file;
        }
    }
    std::istream& in = *in_stream;
    std::ostream& out = std::cout;

    std::string dummy_line;
    std::getline(in, dummy_line); // read and ignore the first line
    std::string line;
    std::getline(in, line);
    std::vector<char> a(line.begin(), line.end());

    int i = 0;
    int one = 0;
    int two = 0;
    bool insideParenthesis = false;

    while (i != (int)a.size()) {
        if (a[i] == '(') {
            insideParenthesis = true;
        } else if (a[i] == ')') {
            insideParenthesis = false;
        } else if (std::isalpha(a[i])) {
            i--;
        }
        if (insideParenthesis) { // inside
            while (++i != (int)a.size() && a[i] != ')' && !std::isalpha(a[i]));
            if (i == (int)a.size() || !std::isalpha(a[i])) {
                continue;
            }
            while (std::isalpha(a[++i]));
            two++;
        } else {
            while (++i != (int)a.size() && a[i] != '(' && !std::isalpha(a[i]));
            if (i == (int)a.size() || !std::isalpha(a[i])) {
                continue;
            }
            int j = i;
            while (++i != (int)a.size() && std::isalpha(a[i]));
            one = std::max(one, i - j);
        }
    }

    out << one << " " << two << "\n";

